#pragma once
#include "Expansion.h"
#include <iostream>
static int auditMultisampleBatch(const juce::File& manifest,const juce::File& output){
 using namespace juce;using namespace noctrl;auto input=JSON::parse(manifest.loadFileAsString());auto* list=input.getArray();if(!list)return 249;Array<var> results;int failures=0;
 for(auto& item:*list){auto folder=File(item.getProperty("path",{}).toString());auto files=folder.findChildFiles(File::findFiles,false,"*.sfz");auto* record=new DynamicObject();record->setProperty("name",item.getProperty("name",{}));record->setProperty("folder",folder.getFullPathName());String error;bool ok=files.size()==1;int zones=0;double energy=0;float peak=0;
  if(ok){auto processor=std::make_unique<SynthProcessor>();ok=processor->loadOscillatorAsset(0,files[0],4,error);if(ok){auto assets=std::atomic_load(&processor->importedAssets);auto& regions=assets->expansion->osc[0].regions;zones=(int)regions.size();for(auto& region:regions)if(!region.sample||region.sample->audio.getNumSamples()<2){ok=false;error="Missing or empty region sample";}if(ok&&!regions.empty()){auto region=regions[0];int key=jlimit(0,127,(region.lo+region.hi)/2),velocity=jlimit(1,127,(region.lowVelocity+region.highVelocity)/2);processor->set("osc1routing",3);processor->set("osc2enabled",0);processor->set("osc3enabled",0);processor->set("noise",0);processor->set("sub",0);processor->prepareToPlay(48000,512);for(int block=0;block<64;++block){AudioBuffer<float> audio(2,512);MidiBuffer midi;if(block==0)midi.addEvent(MidiMessage::noteOn(1,key,(uint8)velocity),0);processor->processBlock(audio,midi);for(int channel=0;channel<2;++channel)for(int sample=0;sample<512;++sample){float value=audio.getSample(channel,sample);if(!std::isfinite(value)||std::abs(value)>1.001f){ok=false;error="Invalid audio output";}peak=jmax(peak,std::abs(value));energy+=value*value;}}if(energy<1e-12){ok=false;error="Audition was silent";}}else if(regions.empty()){ok=false;error="No SFZ zones";}}}
  else error="Instrument SFZ missing or ambiguous";
  record->setProperty("ok",ok);record->setProperty("zones",zones);record->setProperty("energy",energy);record->setProperty("peak",peak);record->setProperty("error",error);results.add(var(record));if(!ok)++failures;output.getParentDirectory().createDirectory();output.replaceWithText(JSON::toString(var(results),true));std::cout<<(ok?"PASS ":"FAIL ")<<item.getProperty("name",{}).toString()<<" zones="<<zones<<" peak="<<peak<<" "<<error<<"\n";
 }
 std::cout<<"AUDIT: "<<results.size()<<" instruments, "<<failures<<" failures\n";return failures?249:0;
}
